import React, { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import { userAPI, petsAPI, adminAPI } from "../services/api";
import { useNavigate } from "react-router-dom";

// Helper function to get full image URL
const getImageUrl = (imagePath) => {
  if (!imagePath) return "/default-pet.png";
  if (imagePath.startsWith("http")) return imagePath;
  return `http://localhost:8000${imagePath}`;
};

const AdminDashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  
  // State management
  const [activeTab, setActiveTab] = useState("dashboard");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  
  // Dashboard Stats
  const [dashboardStats, setDashboardStats] = useState(null);
  
  // Pending Requests
  const [pendingLostReports, setPendingLostReports] = useState([]);
  const [pendingFoundReports, setPendingFoundReports] = useState([]);
  const [pendingAdoptionRequests, setPendingAdoptionRequests] = useState([]);
  const [pendingAdoptionPosts, setPendingAdoptionPosts] = useState([]);
  
  // All Pets
  const [allLostPets, setAllLostPets] = useState([]);
  const [allAdoptionPets, setAllAdoptionPets] = useState([]);
  
  // Search and Filter
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");
  
  // Notifications
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  
  // Detail Modal
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [modalType, setModalType] = useState(""); // 'report' or 'adoption'
  
  // Profile Dropdown
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);

  // Check if user is admin
  useEffect(() => {
    if (user && user.role !== 'admin') {
      navigate('/dashboard');
    }
  }, [user, navigate]);

  // Load initial data
  useEffect(() => {
    if (user?.role === 'admin') {
      loadAllData();
    }
  }, [user]);

  // Auto-hide messages
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(""), 5000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  useEffect(() => {
    if (successMessage) {
      const timer = setTimeout(() => setSuccessMessage(""), 5000);
      return () => clearTimeout(timer);
    }
  }, [successMessage]);

  const loadAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        loadDashboardStats(),
        loadPendingReports(),
        loadPendingAdoptions(),
        loadAllPets(),
        loadNotifications(),
      ]);
    } catch (err) {
      console.error("Error loading admin data:", err);
      setError("Failed to load dashboard data");
    } finally {
      setLoading(false);
    }
  };

  const loadDashboardStats = async () => {
    try {
      const response = await adminAPI.getDashboardStats();
      if (response.data.success) {
        setDashboardStats(response.data.stats);
      }
    } catch (err) {
      console.error("Error loading stats:", err);
    }
  };

  const loadPendingReports = async () => {
    try {
      // Get all user reports and filter pending ones
      const response = await userAPI.getUserReports();
      if (response.data.success) {
        const reports = response.data.reports || [];
        const lost = reports.filter(r => r.report_type === 'LOST' && r.report_status === 'PENDING');
        const found = reports.filter(r => r.report_type === 'RESCUE' && r.report_status === 'PENDING');
        setPendingLostReports(lost);
        setPendingFoundReports(found);
      }
    } catch (err) {
      console.error("Error loading pending reports:", err);
    }
  };

  const loadPendingAdoptions = async () => {
    try {
      const response = await adminAPI.filterAdoptionRequests({ status: 'pending' });
      if (response.data.success) {
        setPendingAdoptionRequests(response.data.adoptions || []);
      }
      
      const postsResponse = await adminAPI.getPendingAdoptionPosts();
      if (postsResponse.data.success) {
        setPendingAdoptionPosts(postsResponse.data.posts || []);
      }
    } catch (err) {
      console.error("Error loading pending adoptions:", err);
    }
  };

  const loadAllPets = async () => {
    try {
      const lostResponse = await userAPI.getAllLostReports();
      if (lostResponse.data.success) {
        setAllLostPets(lostResponse.data.reports || []);
      }
      
      const adoptResponse = await userAPI.getAvailableAdoptionPets();
      if (adoptResponse.data.success) {
        setAllAdoptionPets(adoptResponse.data.pets || []);
      }
    } catch (err) {
      console.error("Error loading all pets:", err);
    }
  };

  const loadNotifications = async () => {
    try {
      const response = await adminAPI.getNotifications();
      if (response.data.success) {
        const notifs = response.data.notifications || [];
        setNotifications(notifs);
        setUnreadCount(notifs.filter(n => !n.is_read).length);
      }
    } catch (err) {
      console.error("Error loading notifications:", err);
    }
  };

  const handleApproveReport = async (reportId) => {
    try {
      setLoading(true);
      await adminAPI.approveReport(reportId);
      setSuccessMessage("Report approved successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to approve report");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectReport = async (reportId) => {
    try {
      setLoading(true);
      await adminAPI.rejectReport(reportId);
      setSuccessMessage("Report rejected successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to reject report");
    } finally {
      setLoading(false);
    }
  };

  const handleApproveAdoption = async (adoptionId) => {
    try {
      setLoading(true);
      await adminAPI.approveAdoption(adoptionId);
      setSuccessMessage("Adoption request approved successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to approve adoption");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectAdoption = async (adoptionId) => {
    try {
      setLoading(true);
      await adminAPI.rejectAdoption(adoptionId);
      setSuccessMessage("Adoption request rejected successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to reject adoption");
    } finally {
      setLoading(false);
    }
  };

  const viewDetails = (item, type) => {
    setSelectedItem(item);
    setModalType(type);
    setShowDetailModal(true);
  };

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-purple-50">
      {/* Header */}
      <header className="bg-white shadow-lg sticky top-0 z-50 border-b-4 border-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            {/* Logo */}
            <div className="flex items-center gap-3">
              <span className="text-4xl">🐾</span>
              <div>
                <h1 className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                  Admin Dashboard
                </h1>
                <p className="text-sm text-gray-600">Pet Rescue Management System</p>
              </div>
            </div>

            {/* Right Section */}
            <div className="flex items-center gap-4">
              {/* Notifications */}
              <div className="relative">
                <button
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="relative p-2 rounded-full hover:bg-gray-100 transition-colors"
                >
                  <span className="text-2xl">🔔</span>
                  {unreadCount > 0 && (
                    <span className="absolute top-0 right-0 bg-red-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center font-bold">
                      {unreadCount}
                    </span>
                  )}
                </button>

                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-2xl border border-gray-200 max-h-96 overflow-y-auto z-50">
                    <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                      <h3 className="font-bold text-lg">Notifications</h3>
                      <button
                        onClick={() => setShowNotifications(false)}
                        className="text-gray-500 hover:text-gray-700"
                      >
                        ✕
                      </button>
                    </div>
                    <div className="divide-y divide-gray-100">
                      {notifications.length > 0 ? (
                        notifications.map((notif) => (
                          <div
                            key={notif.id}
                            className={`p-4 hover:bg-gray-50 cursor-pointer ${
                              !notif.is_read ? "bg-blue-50" : ""
                            }`}
                          >
                            <p className="text-sm font-medium">{notif.message}</p>
                            <p className="text-xs text-gray-500 mt-1">
                              {new Date(notif.created_at).toLocaleString()}
                            </p>
                          </div>
                        ))
                      ) : (
                        <div className="p-8 text-center text-gray-500">
                          <span className="text-4xl block mb-2">📭</span>
                          No notifications
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>

              {/* Profile Dropdown */}
              <div className="relative">
                <button
                  onClick={() => setShowProfileDropdown(!showProfileDropdown)}
                  className="flex items-center gap-2 px-4 py-2 rounded-full bg-gradient-to-r from-primary-blue to-primary-teal text-white hover:shadow-lg transition-all"
                >
                  <span className="text-lg">👤</span>
                  <span className="font-semibold">{user?.username || "Admin"}</span>
                </button>

                {showProfileDropdown && (
                  <div className="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-2xl border border-gray-200 z-50">
                    <div className="p-2">
                      <button
                        onClick={handleLogout}
                        className="w-full px-4 py-2 text-left hover:bg-red-50 rounded-lg text-red-600 font-semibold flex items-center gap-2"
                      >
                        <span>🚪</span>
                        Logout
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Success/Error Messages */}
      {error && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-4">
          <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-lg shadow-lg animate-slideUp">
            <p className="font-bold">Error</p>
            <p>{error}</p>
          </div>
        </div>
      )}

      {successMessage && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-4">
          <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded-lg shadow-lg animate-slideUp">
            <p className="font-bold">Success</p>
            <p>{successMessage}</p>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Navigation Tabs */}
        <div className="flex flex-wrap gap-2 mb-8 bg-white p-2 rounded-2xl shadow-lg">
          {[
            { id: "dashboard", label: "📊 Dashboard", icon: "📊" },
            { id: "pending-reports", label: "📝 Pending Reports", icon: "📝" },
            { id: "pending-adoptions", label: "🏠 Adoption Requests", icon: "🏠" },
            { id: "all-pets", label: "🐾 All Pets", icon: "🐾" },
            { id: "search", label: "🔍 Search & Filter", icon: "🔍" },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-1 min-w-fit px-6 py-3 rounded-xl font-semibold transition-all duration-300 ${
                activeTab === tab.id
                  ? "bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white shadow-lg scale-105"
                  : "text-gray-600 hover:bg-gray-100"
              }`}
            >
              <span className="mr-2">{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Dashboard Overview */}
        {activeTab === "dashboard" && (
          <div className="space-y-6">
            <h2 className="text-3xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
              Dashboard Overview
            </h2>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                {
                  title: "Pending Reports",
                  value: pendingLostReports.length + pendingFoundReports.length,
                  icon: "📝",
                  color: "from-blue-500 to-blue-600",
                  bg: "bg-blue-50",
                },
                {
                  title: "Adoption Requests",
                  value: pendingAdoptionRequests.length,
                  icon: "🏠",
                  color: "from-purple-500 to-purple-600",
                  bg: "bg-purple-50",
                },
                {
                  title: "Total Lost Pets",
                  value: allLostPets.length,
                  icon: "🔍",
                  color: "from-orange-500 to-orange-600",
                  bg: "bg-orange-50",
                },
                {
                  title: "Pets for Adoption",
                  value: allAdoptionPets.length,
                  icon: "❤️",
                  color: "from-pink-500 to-pink-600",
                  bg: "bg-pink-50",
                },
              ].map((stat, index) => (
                <div
                  key={index}
                  className={`${stat.bg} rounded-2xl p-6 shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-gray-200`}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-gray-600 text-sm font-medium mb-1">
                        {stat.title}
                      </p>
                      <p className="text-4xl font-bold text-gray-800">
                        {stat.value}
                      </p>
                    </div>
                    <div className={`text-5xl bg-gradient-to-br ${stat.color} p-4 rounded-2xl shadow-lg`}>
                      <span className="filter drop-shadow-lg">{stat.icon}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Quick Actions */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-gray-800">
                Quick Actions
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                  {
                    label: "View Pending Reports",
                    action: () => setActiveTab("pending-reports"),
                    icon: "📝",
                    color: "from-blue-500 to-blue-600",
                  },
                  {
                    label: "Review Adoptions",
                    action: () => setActiveTab("pending-adoptions"),
                    icon: "🏠",
                    color: "from-purple-500 to-purple-600",
                  },
                  {
                    label: "Browse All Pets",
                    action: () => setActiveTab("all-pets"),
                    icon: "🐾",
                    color: "from-green-500 to-green-600",
                  },
                  {
                    label: "Search Pets",
                    action: () => setActiveTab("search"),
                    icon: "🔍",
                    color: "from-orange-500 to-orange-600",
                  },
                ].map((action, index) => (
                  <button
                    key={index}
                    onClick={action.action}
                    className={`p-4 rounded-xl bg-gradient-to-r ${action.color} text-white font-semibold hover:shadow-lg transform hover:scale-105 transition-all duration-200 flex items-center justify-center gap-2`}
                  >
                    <span className="text-2xl">{action.icon}</span>
                    {action.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Pending Reports Tab */}
        {activeTab === "pending-reports" && (
          <div className="space-y-6">
            <h2 className="text-3xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
              Pending Reports
            </h2>

            {/* Lost Pet Reports */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-blue-600 flex items-center gap-2">
                <span>🔍</span>
                Pending Lost Pet Reports ({pendingLostReports.length})
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {pendingLostReports.length > 0 ? (
                  pendingLostReports.map((report) => (
                    <div
                      key={report.id}
                      className="bg-gradient-to-br from-blue-50 to-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-200"
                    >
                      <div className="relative h-56 overflow-hidden rounded-t-xl">
                        <img
                          src={getImageUrl(report.photo)}
                          alt={report.pet_name}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            e.target.src = "/default-pet.png";
                          }}
                        />
                        <div className="absolute top-2 right-2">
                          <span className="px-3 py-1 bg-yellow-500 text-white text-xs font-bold rounded-full">
                            PENDING
                          </span>
                        </div>
                      </div>
                      <div className="p-5 space-y-3">
                        <h4 className="text-xl font-bold text-gray-800">
                          {report.pet_name}
                        </h4>
                        <div className="space-y-2 text-sm text-gray-600">
                          <p><strong>Type:</strong> {report.animal_type}</p>
                          {report.pet_breed && (
                            <p><strong>Breed:</strong> {report.pet_breed}</p>
                          )}
                          {report.pet_location && (
                            <p><strong>Location:</strong> {report.pet_location}</p>
                          )}
                          <p><strong>Reported by:</strong> {report.owner_username || "Unknown"}</p>
                        </div>
                        <div className="flex gap-2 pt-3">
                          <button
                            onClick={() => viewDetails(report, 'lost-report')}
                            className="flex-1 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 font-semibold"
                          >
                            View Details
                          </button>
                          <button
                            onClick={() => handleApproveReport(report.id)}
                            className="flex-1 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 font-semibold"
                          >
                            ✓ Approve
                          </button>
                          <button
                            onClick={() => handleRejectReport(report.id)}
                            className="flex-1 px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 font-semibold"
                          >
                            ✕ Reject
                          </button>
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full text-center py-16">
                    <span className="text-6xl block mb-4">✅</span>
                    <p className="text-gray-500 text-lg">No pending lost pet reports</p>
                  </div>
                )}
              </div>
            </div>

            {/* Found/Rescue Pet Reports */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-green-600 flex items-center gap-2">
                <span>🦸</span>
                Pending Rescue Reports ({pendingFoundReports.length})
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {pendingFoundReports.length > 0 ? (
                  pendingFoundReports.map((report) => (
                    <div
                      key={report.id}
                      className="bg-gradient-to-br from-green-50 to-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-green-200"
                    >
                      <div className="relative h-56 overflow-hidden rounded-t-xl">
                        <img
                          src={getImageUrl(report.photo)}
                          alt={report.pet_name}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            e.target.src = "/default-pet.png";
                          }}
                        />
                        <div className="absolute top-2 right-2">
                          <span className="px-3 py-1 bg-yellow-500 text-white text-xs font-bold rounded-full">
                            PENDING
                          </span>
                        </div>
                      </div>
                      <div className="p-5 space-y-3">
                        <h4 className="text-xl font-bold text-gray-800">
                          {report.pet_name}
                        </h4>
                        <div className="space-y-2 text-sm text-gray-600">
                          <p><strong>Type:</strong> {report.animal_type}</p>
                          {report.pet_breed && (
                            <p><strong>Breed:</strong> {report.pet_breed}</p>
                          )}
                          {report.pet_location && (
                            <p><strong>Location:</strong> {report.pet_location}</p>
                          )}
                          <p><strong>Reported by:</strong> {report.owner_username || "Unknown"}</p>
                        </div>
                        <div className="flex gap-2 pt-3">
                          <button
                            onClick={() => viewDetails(report, 'rescue-report')}
                            className="flex-1 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 font-semibold"
                          >
                            View Details
                          </button>
                          <button
                            onClick={() => handleApproveReport(report.id)}
                            className="flex-1 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 font-semibold"
                          >
                            ✓ Approve
                          </button>
                          <button
                            onClick={() => handleRejectReport(report.id)}
                            className="flex-1 px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 font-semibold"
                          >
                            ✕ Reject
                          </button>
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full text-center py-16">
                    <span className="text-6xl block mb-4">✅</span>
                    <p className="text-gray-500 text-lg">No pending rescue reports</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Pending Adoptions Tab */}
        {activeTab === "pending-adoptions" && (
          <div className="space-y-6">
            <h2 className="text-3xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
              Pending Adoption Requests
            </h2>

            {/* Adoption Requests */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-purple-600 flex items-center gap-2">
                <span>🏠</span>
                Adoption Requests ({pendingAdoptionRequests.length})
              </h3>
              <div className="grid grid-cols-1 gap-4">
                {pendingAdoptionRequests.length > 0 ? (
                  pendingAdoptionRequests.map((adoption) => (
                    <div
                      key={adoption.id}
                      className="bg-gradient-to-r from-purple-50 to-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 p-6 border border-purple-200"
                    >
                      <div className="flex items-start gap-4">
                        <div className="w-32 h-32 rounded-xl overflow-hidden flex-shrink-0">
                          <img
                            src={getImageUrl(adoption.pet_image)}
                            alt={adoption.pet_name}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                          />
                        </div>
                        <div className="flex-1">
                          <div className="flex items-start justify-between">
                            <div>
                              <h4 className="text-xl font-bold text-gray-800">
                                {adoption.pet_name}
                              </h4>
                              <p className="text-gray-600">
                                Requested by: <strong>{adoption.user_name}</strong>
                              </p>
                              <p className="text-gray-600 mt-2">
                                <strong>Reason:</strong> {adoption.reason || "No reason provided"}
                              </p>
                              <p className="text-sm text-gray-500 mt-1">
                                Requested on: {new Date(adoption.created_at).toLocaleDateString()}
                              </p>
                            </div>
                            <span className="px-3 py-1 bg-yellow-500 text-white text-xs font-bold rounded-full">
                              PENDING
                            </span>
                          </div>
                          <div className="flex gap-2 mt-4">
                            <button
                              onClick={() => viewDetails(adoption, 'adoption-request')}
                              className="px-6 py-2 bg-purple-500 text-white rounded-lg hover:bg-purple-600 font-semibold"
                            >
                              View Details
                            </button>
                            <button
                              onClick={() => handleApproveAdoption(adoption.id)}
                              className="px-6 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 font-semibold"
                            >
                              ✓ Approve
                            </button>
                            <button
                              onClick={() => handleRejectAdoption(adoption.id)}
                              className="px-6 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 font-semibold"
                            >
                              ✕ Reject
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="text-center py-16">
                    <span className="text-6xl block mb-4">✅</span>
                    <p className="text-gray-500 text-lg">No pending adoption requests</p>
                  </div>
                )}
              </div>
            </div>

            {/* Adoption Posts */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-pink-600 flex items-center gap-2">
                <span>❤️</span>
                Pending Adoption Posts ({pendingAdoptionPosts.length})
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {pendingAdoptionPosts.length > 0 ? (
                  pendingAdoptionPosts.map((post) => (
                    <div
                      key={post.id}
                      className="bg-gradient-to-br from-pink-50 to-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-pink-200"
                    >
                      <div className="relative h-56 overflow-hidden rounded-t-xl">
                        <img
                          src={getImageUrl(post.image)}
                          alt={post.name}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            e.target.src = "/default-pet.png";
                          }}
                        />
                        <div className="absolute top-2 right-2">
                          <span className="px-3 py-1 bg-yellow-500 text-white text-xs font-bold rounded-full">
                            PENDING
                          </span>
                        </div>
                      </div>
                      <div className="p-5 space-y-3">
                        <h4 className="text-xl font-bold text-gray-800">
                          {post.name}
                        </h4>
                        <div className="space-y-2 text-sm text-gray-600">
                          <p><strong>Type:</strong> {post.type}</p>
                          {post.breed && <p><strong>Breed:</strong> {post.breed}</p>}
                          <p><strong>Age:</strong> {post.age} years</p>
                          <p><strong>Posted by:</strong> {post.owner_username || "Unknown"}</p>
                        </div>
                        <div className="flex gap-2 pt-3">
                          <button
                            onClick={() => viewDetails(post, 'adoption-post')}
                            className="flex-1 px-4 py-2 bg-pink-500 text-white rounded-lg hover:bg-pink-600 font-semibold"
                          >
                            View Details
                          </button>
                          <button
                            onClick={() => handleApproveReport(post.report_id)}
                            className="flex-1 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 font-semibold"
                          >
                            ✓ Approve
                          </button>
                          <button
                            onClick={() => handleRejectReport(post.report_id)}
                            className="flex-1 px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 font-semibold"
                          >
                            ✕ Reject
                          </button>
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full text-center py-16">
                    <span className="text-6xl block mb-4">✅</span>
                    <p className="text-gray-500 text-lg">No pending adoption posts</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* All Pets Tab */}
        {activeTab === "all-pets" && (
          <div className="space-y-6">
            <h2 className="text-3xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
              All Pets
            </h2>

            {/* Lost Pets */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-blue-600 flex items-center gap-2">
                <span>🔍</span>
                All Lost Pets ({allLostPets.filter(p => p.report_status === 'ACCEPTED').length})
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {allLostPets.filter(p => p.report_status === 'ACCEPTED').map((pet) => (
                  <div
                    key={pet.id}
                    className="bg-gradient-to-br from-blue-50 to-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-200"
                  >
                    <div className="relative h-48 overflow-hidden rounded-t-xl">
                      <img
                        src={getImageUrl(pet.photo)}
                        alt={pet.pet_name}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.target.src = "/default-pet.png";
                        }}
                      />
                    </div>
                    <div className="p-4 space-y-2">
                      <h4 className="font-bold text-gray-800">{pet.pet_name}</h4>
                      <p className="text-sm text-gray-600">{pet.animal_type}</p>
                      <p className="text-xs text-gray-500">{pet.pet_location}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Adoption Pets */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-pink-600 flex items-center gap-2">
                <span>❤️</span>
                Pets Available for Adoption ({allAdoptionPets.length})
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {allAdoptionPets.map((pet) => (
                  <div
                    key={pet.id}
                    className="bg-gradient-to-br from-pink-50 to-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-pink-200"
                  >
                    <div className="relative h-48 overflow-hidden rounded-t-xl">
                      <img
                        src={getImageUrl(pet.image)}
                        alt={pet.name}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.target.src = "/default-pet.png";
                        }}
                      />
                    </div>
                    <div className="p-4 space-y-2">
                      <h4 className="font-bold text-gray-800">{pet.name}</h4>
                      <p className="text-sm text-gray-600">{pet.type}</p>
                      <p className="text-xs text-gray-500">{pet.age} years • {pet.gender}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Search Tab */}
        {activeTab === "search" && (
          <div className="space-y-6">
            <h2 className="text-3xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
              Search & Filter Pets
            </h2>

            {/* Search Filters */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <input
                  type="text"
                  placeholder="Search by name, breed, location..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-primary-blue focus:border-transparent"
                />
                <select
                  value={filterType}
                  onChange={(e) => setFilterType(e.target.value)}
                  className="px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-primary-blue focus:border-transparent"
                >
                  <option value="all">All Types</option>
                  <option value="dog">Dog</option>
                  <option value="cat">Cat</option>
                  <option value="bird">Bird</option>
                  <option value="other">Other</option>
                </select>
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-primary-blue focus:border-transparent"
                >
                  <option value="all">All Status</option>
                  <option value="lost">Lost</option>
                  <option value="adopt">Available for Adoption</option>
                </select>
              </div>
            </div>

            {/* Search Results */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h3 className="text-2xl font-bold mb-4 text-gray-800">
                Search Results
              </h3>
              <p className="text-gray-600">
                Showing results for: <strong>{searchQuery || "All"}</strong>
              </p>
              <div className="mt-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {/* Search results will be filtered here */}
                <div className="col-span-full text-center py-16">
                  <span className="text-6xl block mb-4">🔍</span>
                  <p className="text-gray-500 text-lg">Enter search criteria to find pets</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;
